#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'data/latest.json').read_text(encoding='utf-8')) if (ROOT/'data/latest.json').exists() else {'generated_at':'No scan yet','count':0,'top':[]}
rows=''.join(f"<tr><td>{i}</td><td><a href='{x['url']}' target='_blank'>{x['full_name']}</a></td><td>{x['stars']:,}</td><td>{x['license'] or 'Unknown'}</td><td><b>{x['score']}</b></td><td>{x['best_path']}</td></tr>" for i,x in enumerate(data['top'],1))
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Open Source Opportunity Radar</title><style>body{{font-family:system-ui;margin:0;background:#0b1020;color:#e8ecf5}}main{{max-width:1200px;margin:auto;padding:32px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}}.card{{background:#151c31;padding:20px;border-radius:14px}}table{{width:100%;margin-top:24px;border-collapse:collapse;background:#151c31}}td,th{{padding:12px;border-bottom:1px solid #2a3552;text-align:left}}a{{color:#8db4ff}}@media(max-width:800px){{.grid{{grid-template-columns:1fr}}}}</style></head><body><main><h1>Open Source Opportunity Radar</h1><p>Generated: {data['generated_at']}</p><div class="grid"><div class="card"><h2>{data['count']}</h2><p>Repositories scanned</p></div><div class="card"><h2>{len(data['top'])}</h2><p>Ranked opportunities</p></div><div class="card"><h2>Daily</h2><p>Automatic scan cadence</p></div></div><h2>Top Opportunities</h2><table><thead><tr><th>#</th><th>Repository</th><th>Stars</th><th>License</th><th>Score</th><th>Best money path</th></tr></thead><tbody>{rows}</tbody></table></main></body></html>'''
out=ROOT/'dashboard'/'index.html'; out.parent.mkdir(exist_ok=True); out.write_text(html,encoding='utf-8')
